package de.schaepi.puls180;
import android.graphics.*;import android.graphics.pdf.PdfDocument;import java.util.*;import java.time.*;import java.time.format.*;
public final class ReportSummary{
public static double[] averages(ArrayList<String[]> rows){double sys=0,dia=0,pulse=0;int count=0;for(String[] r:rows){String[] bp=r[1].split(" / ");sys+=Double.parseDouble(bp[0]);dia+=Double.parseDouble(bp[1]);try{double v=Double.parseDouble(r[2]);if(Double.isFinite(v)&&v>0){pulse+=v;count++;}}catch(NumberFormatException ignored){}}return new double[]{sys/rows.size(),dia/rows.size(),count==0?Double.NaN:pulse/count,count};}
private static void line(Canvas c,Paint p,String s,int y,int size){p.setTextSize(size);p.setColor(Color.BLACK);c.drawText(s,36,y,p);}
public static void draw(PdfDocument doc,ArrayList<String[]> rows,String period,String name,int pages){PdfDocument.Page page=doc.startPage(new PdfDocument.PageInfo.Builder(595,842,1).create());Canvas c=page.getCanvas();Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);line(c,p,"Blutdruckbericht für den Arzt",48,21);line(c,p,name.isEmpty()?"Patientendaten: nicht angegeben":name,78,12);line(c,p,period,100,10);line(c,p,"Erstellt am: "+LocalDateTime.now().format(DateTimeFormatter.ofPattern("dd.MM.yyyy HH:mm")),119,10);double[] a=averages(rows);line(c,p,"Ausgewertete Messungen: "+rows.size(),153,12);line(c,p,String.format(Locale.GERMANY,"Mittelwert Blutdruck: %.1f / %.1f mmHg",a[0],a[1]),179,14);line(c,p,Double.isNaN(a[2])?"Puls: keine zugeordneten Werte":String.format(Locale.GERMANY,"Mittelwert Puls: %.1f bpm (aus %.0f Messungen)",a[2],a[3]),204,12);
line(c,p,"Arithmetische Mittelwerte aller ausgewählten, sichtbaren Messungen.",231,10);line(c,p,"Häufigere Messungen an einzelnen Tagen beeinflussen den Mittelwert stärker.",247,10);
line(c,p,"Blutdruckverlauf – mmHg",282,14);
ArrayList<String[]> sorted=new ArrayList<>(rows);DateTimeFormatter fmt=DateTimeFormatter.ofPattern("dd.MM.yyyy HH:mm:ss");sorted.sort(Comparator.comparing(r->LocalDateTime.parse(r[0],fmt)));long first=LocalDateTime.parse(sorted.get(0)[0],fmt).toEpochSecond(ZoneOffset.UTC),last=LocalDateTime.parse(sorted.get(sorted.size()-1)[0],fmt).toEpochSecond(ZoneOffset.UTC);double low=Double.MAX_VALUE,high=0;for(String[] r:sorted){String[] bp=r[1].split(" / ");low=Math.min(low,Double.parseDouble(bp[1]));high=Math.max(high,Double.parseDouble(bp[0]));}low=Math.floor((low-10)/10)*10;high=Math.ceil((high+10)/10)*10;
for(int i=0;i<=4;i++){float y=320+i*45;p.setColor(Color.LTGRAY);p.setStrokeWidth(1);c.drawLine(70,y,550,y,p);p.setColor(Color.BLACK);p.setTextSize(9);c.drawText(String.format(Locale.GERMANY,"%.0f",high-(high-low)*i/4),36,y+3,p);}
for(int series=0;series<2;series++){p.setColor(series==0?Color.rgb(170,35,45):Color.rgb(25,80,180));p.setStrokeWidth(2);float previousX=0,previousY=0;boolean initial=true;for(String[] r:sorted){long time=LocalDateTime.parse(r[0],fmt).toEpochSecond(ZoneOffset.UTC);float x=last==first?310:70+480f*(time-first)/(last-first);double value=Double.parseDouble(r[1].split(" / ")[series]);float y=320+(float)(180*(high-value)/(high-low));if(!initial)c.drawLine(previousX,previousY,x,y,p);c.drawCircle(x,y,2.5f,p);previousX=x;previousY=y;initial=false;}}
line(c,p,sorted.get(0)[0]+"   bis   "+sorted.get(sorted.size()-1)[0],523,9);line(c,p,"Rot: systolisch   /   Blau: diastolisch",548,10);line(c,p,"Zeitachse nach Messzeit; als Empfangszeit markierte Einträge können abweichen.",571,10);line(c,p,"Die folgenden Seiten enthalten alle ausgewählten Messungen und Notizen.",606,10);line(c,p,"Gerätehinweise sind keine Diagnose. Fehlende Hinweise bedeuten nicht",627,10);line(c,p,"automatisch, dass kein unregelmäßiger Herzschlag vorlag.",643,10);line(c,p,"Zur ärztlichen Besprechung – keine automatische Diagnose oder Therapieempfehlung.",675,10);line(c,p,"Seite 1 von "+pages,813,10);doc.finishPage(page);}
}



